function cxExtendExcel(bytes,tables){const entries=[],view=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength),decode=new TextDecoder();let at=0;while(at+30<bytes.length&&view.getUint32(at,true)===0x04034b50){if(view.getUint16(at+8,true)!==0)throw Error('지원되지 않는 기존 Excel 압축 형식');let size=view.getUint32(at+18,true),n=view.getUint16(at+26,true),extra=view.getUint16(at+28,true),start=at+30+n+extra;entries.push([decode.decode(bytes.slice(at+30,at+30+n)),bytes.slice(start,start+size)]);at=start+size;}let map=new Map(entries),book=decode.decode(map.get('xl/workbook.xml')),rels=decode.decode(map.get('xl/_rels/workbook.xml.rels')),types=decode.decode(map.get('[Content_Types].xml'));let count=(book.match(/<sheet /g)||[]).length,maxRel=Math.max(0,...[...rels.matchAll(/Id="rId(\d+)"/g)].map(m=>Number(m[1])));
 for(const [name,records]of tables){count++;maxRel++;const data=records.length?records:[{Status:'자료 부족 / 원본 재추출 필요'}],keys=[...new Set(data.flatMap(r=>Object.keys(r)))],cell=(v,col,row,header=false)=>{let id=cxColumn(col)+row;if(typeof v==='number'&&Number.isFinite(v))return '<c r="'+id+'" s="1"><v>'+v+'</v></c>';if(v===null||v===undefined)return '<c r="'+id+'"/>';return '<c r="'+id+'" s="'+(header?'2':'3')+'" t="inlineStr"><is><t xml:space="preserve">'+cxXML(typeof v==='object'?JSON.stringify(v):v)+'</t></is></c>';};let sheet='<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" state="frozen"/></sheetView></sheetViews><sheetData><row r="1">'+keys.map((k,j)=>cell(k,j,1,true)).join('')+'</row>'+data.map((r,i)=>'<row r="'+(i+2)+'">'+keys.map((k,j)=>cell(r[k],j,i+2)).join('')+'</row>').join('')+'</sheetData><autoFilter ref="A1:'+cxColumn(keys.length-1)+(data.length+1)+'"/></worksheet>';map.set('xl/worksheets/sheet'+count+'.xml',encoder.encode(sheet));book=book.replace('</sheets>','<sheet name="'+cxXML(name)+'" sheetId="'+count+'" r:id="rId'+maxRel+'"/></sheets>');rels=rels.replace('</Relationships>','<Relationship Id="rId'+maxRel+'" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet'+count+'.xml"/></Relationships>');types=types.replace('</Types>','<Override PartName="/xl/worksheets/sheet'+count+'.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>');}
 map.set('xl/workbook.xml',encoder.encode(book));map.set('xl/_rels/workbook.xml.rels',encoder.encode(rels));map.set('[Content_Types].xml',encoder.encode(types));return zip([...map]);}
