function cxChartPNG(canvas){return researchCanvasPNG(canvas);}
function cxOnsetRatePNG(){let canvas=document.createElement('canvas');canvas.width=1500;canvas.height=540;let a=researchVAssessment(),data=a.curve;researchChart(canvas,[{label:'Brightness · '+researchModeLabel(),color:'#087f83',points:data}],{title:'Brightness · Gas ON / Onset / Rate interval',yLabel:'Brightness (%)',range:[0,100],subtitle:config().timing_source+' · 보라: Onset / 상단 막대: V 속도 구간 · 평활화 없음',phases:researchPhases()});if(data.length){let ctx=canvas.getContext('2d'),low=data[0][0],high=data.at(-1)[0],X=t=>72+(t-low)/(high-low||1)*(1500-96);ctx.save();for(const r of a.cycles){for(const [t,color,label]of [[r.gas_on_s,'#c1784a','Gas ON'],[r.onset_time_s,'#9776c7','Onset']])if(Number.isFinite(t)&&t>=low&&t<=high){ctx.strokeStyle=color;ctx.setLineDash([5,4]);ctx.beginPath();ctx.moveTo(X(t),78);ctx.lineTo(X(t),476);ctx.stroke();ctx.fillStyle=color;ctx.fillText(label,X(t)+3,label==='Onset'?103:88);}if(Number.isFinite(r.V_rate_start_s)&&Number.isFinite(r.V_rate_end_s)){ctx.strokeStyle='#ad7591';ctx.setLineDash([]);ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(X(r.V_rate_start_s),112);ctx.lineTo(X(r.V_rate_end_s),112);ctx.stroke();}}ctx.restore();}return researchCanvasPNG(canvas);}
researchFiles=function(d){return [...cxFiles(d),['ROI_Comparison.csv',csv(d.roi_comparison)],['Responsive_Pixels.csv',csv(d.responsive_pixels)],['Hue_Audit.csv',csv(d.hue_audit)],['Signal_Audit.csv',csv(d.signal_audit)],['Method_Definitions.csv',csv(d.definitions)],['ROI_Settings.json',JSON.stringify(d.settings.comprehensive_revision.roi,null,2)],['graphs/Responsive_Pixels.png',cxChartPNG($('cxPixelPlot'))],['graphs/Hue_Angles.png',cxChartPNG($('cxHuePlot'))],['graphs/Hue_Cos.png',cxChartPNG($('cxCosPlot'))],['graphs/Onset_Rate_Brightness.png',cxOnsetRatePNG()]];};
const cxReport=buildReportPages;
buildReportPages=function(a,candidates,q,cal,info,photos){const pages=cxReport(a,candidates,q,cal,info,photos),c=config(),roi=extractionSettings?.roi_metadata;
 let body='<div class="rFlow"><h3>고정 ROI 및 Edge</h3><p>'+rEsc(roi?roi.sensor_width_px+'×'+roi.sensor_height_px+' px, Edge '+roi.edge_distance_px+' px ('+roi.edge_mode+'), '+roi.roi_shape+(Number.isFinite(roi.roi_angle_deg)?' '+roi.roi_angle_deg.toFixed(1)+'°':'')+', '+roi.pixel_count+' pixels, sensor area '+roi.roi_area_percent.toFixed(1)+'%':'기존 CSV의 픽셀 ROI 정보 없음; 원본 재추출 필요')+'</p><p>960×540 분석 좌표, 정사각 침식 커널, 회전 탐색 내부 직사각형. 5° 탐색 후 주변 1° 탐색으로 전역 최대를 보장하지 않습니다. 분석은 원본 픽셀을 사용하고 위치·크기·각도는 고정합니다.</p><h3>V 반응 시작 및 활성 구간 평균 속도</h3>'+rTable(['회차','V Onset(s)','V 속도(%p/min)','속도 구간(s)','픽셀 비율 최대(%)'],a.cycles.map(r=>[r.cycle,rText(r.V_onset_s),rText(r.V_reaction_rate_pct_point_per_min),Number.isFinite(r.V_rate_start_s)?r.V_rate_start_s.toFixed(1)+'–'+r.V_rate_end_s.toFixed(1):'계산 불가',rText(r.responsive_pixel_percent_max)]))+'<p>'+rEsc(c.timing_source)+' · Onset: |신호−Baseline|>'+c.onset_rule.k+'×SD, 연속 3표본. SD≈0은 계산 보류. 속도: Onset부터 t90 또는 유효 노출 종료까지의 ΔBrightness/분. 반응 픽셀: 각 픽셀의 Baseline SD·최소 변화 대비 비율이며 95% 합격 판정이 아닙니다.</p></div>';pages.push(rPage('부록 - ROI 및 반응 균일성·속도',body));
 const appendix=pages.at(-1),at=appendix.body.lastIndexOf('</div>');let png=cxOnsetRatePNG(),binary='';for(const byte of png)binary+=String.fromCharCode(byte);appendix.body=appendix.body.slice(0,at)+'<img style="width:100%;height:auto;margin:6pt 0" alt="V Onset and rate intervals" src="data:image/png;base64,'+btoa(binary)+'"><p>'+rEsc(a.cycles.map(r=>r.cycle+'회 V 속도: '+r.V_rate_status).join(' / '))+'</p>'+appendix.body.slice(at);
 pages.push(rPage('부록 - 수식 근거 및 H 검산','<div class="rFlow"><h3>논문식과 자체 기준</h3><p>2020 Eq.(3) 픽셀 V와 Eq.(4) Response 유지. Eq.(2) S는 표준 HSV S와 별도 후보. Onset, 속도 차분, 픽셀 반응 기준은 2025/2020 개념을 참고한 자체 정의입니다.</p><h3>H 그래프와 CSV</h3><p>Raw/Relative H(°), 연속 H(°), cos(H−240°)(무차원)는 서로 다른 신호입니다. H는 S 가중 원형 평균이며 낮은 S/coherence와 제외 표본을 함께 기록합니다. 계산·표시 평활화 없음. 정확한 시각·ROI·보정·디코더 조건을 맞추어 원본 검산합니다.</p><h3>정식 적용 보류</h3><p>2025 Eq.(3)의 10^n 정규화와 보고 RGB Index 범위가 일치하지 않고 공간 추출 범위도 충분히 명시되지 않아 수치를 임의로 맞추지 않았습니다. Eq.(1)의 ΔV와 gas/air 분모 선택은 운용 정의가 불명확하여 2020 Response를 교체하지 않았습니다.</p><p>2020 DOI 10.1016/j.snb.2020.128612 · 2025 DOI 10.1038/s41746-025-01851-4. Shape factor는 픽셀 격자 윤곽의 보조 형태량이며 감도·정확도 지표가 아닙니다.</p></div>'));return pages;};
const cxSchedule=schedule,cxInitial=initialRecoveryPhase;
initialRecoveryPhase=function(c=config()){return cxKnownSchedule(c)?cxInitial(c):null;};
schedule=function(){cxSchedule();if(!cxKnownSchedule(config())){$('experimentTimeline').replaceChildren(uiEl('p','주입 시각 미확정 · 기록 시각 입력 또는 색 변화 추정 후 시간 구간을 표시합니다.','researchNote'));$('schedule').textContent='실험 구간의 지속시간만 설정됨 · 실제 시작 미확정';}};
cxInstall();
// Optional absolute timestamps preserve gaps between recorded cycles.
function cxAbsoluteRows(){const root=$('cxAbsoluteRows');root.replaceChildren();for(const [i,r]of cyclePlan.entries()){let tr=uiEl('tr');tr.append(uiEl('td',i+1));for(const k of ['concentration_ppm','gas_on_s','gas_off_s','recovery_end_s']){let td=uiEl('td'),input=uiEl('input');input.type='number';input.step='any';input.min=0;input.value=k==='concentration_ppm'?r[k]??'':cxKnownSchedule(config())?r[k]:'';input.dataset.key=k;input.setAttribute('aria-label',(i+1)+'회 '+k);td.append(input);tr.append(td);}root.append(tr);}}
const absolute=uiEl('details',undefined,'researchFold');absolute.innerHTML='<summary>회차별 기록 시각 직접 입력</summary><div class="researchStats"><table><thead><tr><th>회차</th><th>ppm</th><th>주입 시작(s)</th><th>제거 시작(s)</th><th>회복 종료(s)</th></tr></thead><tbody id="cxAbsoluteRows"></tbody></table></div><button id="cxApplyAbsolute">입력 시각 적용</button><p class="researchNote">회차 사이 빈 구간도 그대로 유지합니다. 장비 기록 확인 여부는 기존 시각 근거 항목에서 선택하세요.</p>';$('planTable').after(absolute);absolute.ontoggle=()=>{if(absolute.open)cxAbsoluteRows();};$('cxApplyAbsolute').onclick=()=>{try{if(busy)throw Error('추출 완료 후 시간을 변경하세요.');let plan=[...$('cxAbsoluteRows').children].map(tr=>Object.fromEntries([...tr.querySelectorAll('input')].map(input=>[input.dataset.key,input.value===''?(input.dataset.key==='concentration_ppm'?null:NaN):Number(input.value)])));planRanges({...config(),cycle_plan:plan});cyclePlan=plan;$('firstInjection').value=plan[0].gas_on_s;estimatedFirst=null;timingInference=null;timingUnresolved=false;renderPlan();schedule();nativeInvalidateReport();if(rows.length)nativeRefresh();status('입력한 회차별 시각을 적용했습니다. 실제 기록 확인 여부도 선택하세요.');}catch(e){status(e.message,true);}};
let cxLastSample=null;
const cxAuditSample=researchSample;
researchSample=function(roi){let value=cxAuditSample(roi);cxLastSample=value;return value;};
const cxHueVerifyOld=cxVerifyHue;
cxVerifyHue=async function(){if(!rows.length)return;let time=Number($('cxHueTime').value),r=rows.reduce((a,b)=>Math.abs(b.global_time_s-time)<Math.abs(a.global_time_s-time)?b:a);if(!Number.isFinite(r.raw_H_deg)){$('cxHueCheck').textContent='CSV에 Raw H 각도가 없습니다. 전체 색상 시계열 CSV와 추출 설정을 불러오세요.';return;}await cxHueVerifyOld();if(!$('cxHueCheck').textContent.startsWith('재계산 Raw H')||!cxLastSample)return;if(!Number.isFinite(r.roi_pixels_crc32)||r.roi_pixels_crc32!==cxLastSample.roi_pixels_crc32)return;let delta=Math.abs(nativeWrapAngle(cxLastSample.raw_H_deg-r.raw_H_deg));$('cxHueCheck').textContent+=' · 픽셀 CRC 일치: '+(r.raw_S<.05||r.raw_H_coherence<.3?'Hue 신뢰도 부족; 각도 비교 해석 보류':delta<1e-5?'동일 픽셀·계산식·H 결과 일치':'동일 픽셀인데 H 결과 불일치: 계산 버그 점검 대상');};
$('cxHueVerify').onclick=()=>cxVerifyHue();
const cxSelectChannel=nativeSelectChannel;
nativeSelectChannel=function(channel){if(channel==='paper_s'&&rows.length&&!rows.some(r=>Number.isFinite(researchValue(r,'paper_S')))){status('기존 데이터에 픽셀별 논문식 S가 없습니다. 평균 RGB로 만들지 않고 원본 재추출이 필요합니다.',true);$('nativeChannel').value=nativeView.channel;return;}return cxSelectChannel(channel);};
const rgbFold=uiEl('details',undefined,'researchFold');rgbFold.innerHTML='<summary>최종 ROI RGB 평균</summary><canvas id="cxRGBPlot" width="1000" height="340"></canvas><p class="researchNote">선택 보정의 실제 ROI 평균 R·G·B(0–255). 제외 표본은 공백입니다.</p>';$('qualitySummary').closest('section').append(rgbFold);
function cxRGBSeries(){return ['R','G','B'].map((key,i)=>({label:'ROI mean '+key,color:['#c75b59','#33886f','#4979bc'][i],points:rows.map(r=>[r.global_time_s,qualityStatus(r)==='exclude'?null:researchValue(r,key)])}));}
const cxRefreshPrevious=cxRefresh;
cxRefresh=function(){cxRefreshPrevious();researchChart($('cxRGBPlot'),cxRGBSeries(),{title:'최종 ROI RGB 평균',yLabel:'RGB (0–255)',range:[0,255],subtitle:researchModeLabel()+' · 같은 고정 ROI · 평활화 없음'});};
function cxExportChart(kind){let canvas=document.createElement('canvas');canvas.width=1500;canvas.height=540;let options={light:true,subtitle:researchModeLabel()+' · 평활화 없음'},series=[];if(kind==='rgb'){series=cxRGBSeries();Object.assign(options,{title:'Final ROI mean RGB vs Time',yLabel:'RGB (0–255)',range:[0,255]});}else if(kind==='pixels'){let data=cxPixelRecords();series=[{label:'Responsive pixels',color:'#087f83',points:data.map(r=>[r.Time_s,r.Response_pixel_percent])}];Object.assign(options,{title:'ROI Responsive Pixels vs Time',yLabel:'Responsive pixels (%)',range:[0,100],phases:researchPhases()});}else {let h=cxHueRecords();if(kind==='hue'){series=[{label:'CSV / Raw H (°)',color:'#4979bc',points:h.map(r=>[r.Time_s,r.Raw_H_deg])},{label:'Relative H (°)',color:'#c27756',points:h.map(r=>[r.Time_s,r.Relative_H_deg])}];Object.assign(options,{title:'Hue angles · original and Relative',yLabel:'Wrapped Hue (°)',range:[0,360]});}else{series=[{label:'cos(H−240°)',color:'#087f83',points:h.map(r=>[r.Time_s,r.Excluded?null:r.H_cos_transform])}];Object.assign(options,{title:'Hue cosine · different from angle',yLabel:'cos(H−240°), unitless',range:[-1,1]});}}researchChart(canvas,series,options);return researchCanvasPNG(canvas);}
const cxSavedFiles=researchFiles;
researchFiles=function(d){let files=cxSavedFiles(d);for(const [name,kind]of [['graphs/Responsive_Pixels.png','pixels'],['graphs/Hue_Angles.png','hue'],['graphs/Hue_Cos.png','cos']]){let entry=files.find(e=>e[0]===name);if(entry)entry[1]=cxExportChart(kind);}return [...files,['graphs/ROI_Mean_RGB.png',cxExportChart('rgb')]];};
const cxTimeChart=researchChart;
researchChart=function(canvas,series,options={}){if((options.xLabel||'Time (s)').startsWith('Time')){let dt=researchObservedInterval();series=series.map(s=>{let points=[];for(let i=0;i<s.points.length;i++){if(i&&s.points[i][0]-s.points[i-1][0]>dt*1.8)points.push([s.points[i][0],null]);points.push(s.points[i]);}return {...s,points};});}return cxTimeChart(canvas,series,options);};
