function cxUprightRefresh(g){
 const canvas=$('cxUprightROI'),note=$('cxUprightNote');if(!canvas)return false;
 const r=g.selected.rectangle;
 if(g.selected.shape!=='rectangle'||!r){canvas.hidden=true;if(note)note.textContent='윤곽 전체 ROI에는 회전 직사각형 사진이 없습니다.';return false;}
 if(!image||!(image instanceof HTMLCanvasElement||image.complete&&image.naturalWidth)){canvas.hidden=true;return false;}
 if(!$('cxUprightFold').open&&!cxSavingUpright)return true;
 canvas.hidden=false;canvas.width=Math.max(1,Math.round(r.width));canvas.height=Math.max(1,Math.round(r.height));
 const ctx=canvas.getContext('2d');ctx.save();ctx.clearRect(0,0,canvas.width,canvas.height);ctx.translate(canvas.width/2,canvas.height/2);ctx.scale(canvas.width/r.width,canvas.height/r.height);ctx.rotate(-r.angle_deg*Math.PI/180);ctx.translate(-r.center_x,-r.center_y);ctx.drawImage(image,0,0,cxW,cxH);ctx.restore();
 if(note)note.textContent='ROI '+r.width.toFixed(1)+' × '+r.height.toFixed(1)+' px · 원본 각도 '+r.angle_deg.toFixed(1)+'° · '+(cxFrame?.file||'')+' '+(cxFrame?.time_s||0).toFixed(1)+'초. 표시·PNG만 회전 보간; 분석은 원본 '+g.selected.ids.length+'픽셀 그대로.';
 return true;
}

